import type { Cue } from "./types";

/**
 * Guesses whether captions were auto-generated (speech recognition) rather
 * than written by a person. YouTube doesn't tell us directly, but generated
 * captions have little or no sentence punctuation, which is what makes the
 * sentences come out long. Fewer than one . ? ! per 40 words counts as
 * generated; very short tracks are never flagged.
 */
export function looksAutoGenerated(cues: Cue[]): boolean {
  const text = cues.map((c) => c.text).join(" ");
  const words = text.split(/\s+/).filter(Boolean).length;
  if (words < 40) return false;
  const enders = (text.match(/[.?!](?=\s|$|["')\]])/g) ?? []).length;
  return enders / words < 1 / 40;
}
